curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel&exclude_archived=true" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'launch' in ch['name'].lower():
            print(json.dumps(ch, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&limit=999" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        display = u.get('profile', {}).get('display_name', '')
        real = u.get('real_name', '')
        if 'farhan' in u['name'].lower() or 'deebo' in display.lower() or 'deebo' in real.lower() or 'malik' in real.lower():
            print(f'id: {u[\"id\"]}, name: {u[\"name\"]}, real_name: {real}, display_name: {display}')
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST https://slack.com/api/conversations.members -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=C_LAUNCH&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['members']:
        print(m)
else:
    print(json.dumps(data, indent=2))
"
